const get = Object.getOwnPropertyDescriptor(URL.prototype, 'href').get;
if (get.call(new URL('file:///tmp/real%20file')) !== 'file:///tmp/real%20file') throw new Error('actual URL href differs');
let checks = 1;
for (const value of [{}, Object.create(URL.prototype)]) {
  let caught;
  try { get.call(value); } catch (error) { caught = error; }
  if (!(caught instanceof TypeError)) throw new Error('URL href getter accepted an object without URL state');
  checks++;
}
console.log('URL RECEIVER ' + checks + ' CHECKS OK');
